mapper.insert:
INSERT INTO cps_inspection_item (
    item_code, item_name, factory, enabled, remark, created_by, updated_by
) VALUES (
    #{itemCode}, #{itemName}, #{factory}, #{enabled}, #{remark}, #{createdBy}, #{updatedBy}
)

mapper.update:
UPDATE cps_inspection_item
SET enabled = #{enabled}, updated_by = #{updatedBy}
WHERE id = #{id}

mapper.select:
SELECT i.id
FROM cps_inspection_item i
WHERE NOT EXISTS (
          SELECT 1 FROM cps_inspection_item_permission p WHERE p.item_id = i.id
      )
   OR EXISTS (
          SELECT 1 FROM cps_inspection_item_permission p2
          WHERE p2.item_id = i.id AND p2.emp_no = #{empNo}
      )

SELECT COUNT(*)
FROM cps_inspection_item_permission
WHERE item_id = #{itemId}
